// Count jobs by status and filter today's activity
const today = new Date().toISOString().split('T')[0];
const jobs = $input.all().map(i => i.json);

const counts = {
  total: jobs.length,
  applied: 0,
  failed: 0,
  skipped: 0,
  new: 0,
  today_applied: 0,
  today_failed: 0,
  today_skipped: 0
};

for (const job of jobs) {
  const status = (job.status || '').toLowerCase();
  if (status === 'applied') counts.applied++;
  else if (status === 'failed') counts.failed++;
  else if (status === 'skipped') counts.skipped++;
  else if (status === 'new') counts.new++;

  // Check if activity happened today
  if (job.date_applied && job.date_applied.startsWith(today)) {
    if (status === 'applied') counts.today_applied++;
    else if (status === 'failed') counts.today_failed++;
    else if (status === 'skipped') counts.today_skipped++;
  }
}

counts.today_total = counts.today_applied + counts.today_failed + counts.today_skipped;
counts.success_rate = counts.applied > 0 
  ? Math.round((counts.applied / (counts.applied + counts.failed)) * 100) 
  : 0;

return [{ json: counts }];
